// Конфиг из Data Table helios_config (key/value): модель, ID таблицы и папки, chat_id менеджера
const cfg = Object.fromEntries($('Config').all().map(i => [i.json.key, i.json.value]));
const msg = $('Telegram Trigger').first().json.message || {};
const caption = (msg.caption || '').trim();
const text = (msg.text || '').trim();

// Фото: сжатое (photo[]) или файлом-картинкой (document image/*)
let fileId = null;
let mime = 'image/jpeg';
if (msg.photo?.length) fileId = msg.photo[msg.photo.length - 1].file_id;
else if (msg.document && /^image\//.test(msg.document.mime_type || '')) {
  fileId = msg.document.file_id;
  mime = msg.document.mime_type;
}

// Подпись с номером наряда = фото готовой работы; без подписи = фото бланка
const orderFromCaption = (caption.match(/\d{3,6}/) || [])[0] || null;
let kind = 'other';
if (/^\/start(\s|@|$)/.test(text) || /^\/help/.test(text)) kind = 'start';
else if (fileId && orderFromCaption) kind = 'work';
else if (fileId) kind = 'order';

return [{
  json: {
    kind,
    chatId: msg.chat?.id,
    fileId,
    mime,
    orderNo: orderFromCaption,
    model: cfg.llm_model,
    sheetId: cfg.sheet_id,
    driveFolderId: cfg.drive_folder_id,
    managerChatId: cfg.manager_chat_id,
    clinics: String(cfg.clinics || '').split(';').map(s => s.trim()).filter(Boolean),
    doctors: String(cfg.doctors || '').split(';').map(s => s.trim()).filter(Boolean),
  },
}];

// Картинку отправляем в модель как base64 data URL — без промежуточных хранилищ
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = $('Prepare').first().json.mime || 'image/jpeg';
return [{ json: { dataUrl: `data:${mime};base64,${buf.toString('base64')}`, model: $('Prepare').first().json.model } }];

const p = $('Prepare').first().json;
// Поля от под-workflow «HELIOS 02 Распознать наряд»: {поле: {value, confidence}}
const data = $input.first().json.fields || {};

const LABELS = {
  order_number: 'Номер', date: 'Дата', clinic: 'Клиника', doctor: 'Врач',
  patient_initials: 'Пациент', teeth: 'Зубы (FDI)', work_type: 'Вид работы',
  units: 'Кол-во', shade: 'Цвет VITA', due_date: 'Срок', comment: 'Комментарий',
};
const WORK = ['Коронка цирконий', 'Коронка E.max', 'Металлокерамика', 'Винир', 'Мост', 'Вкладка', 'Другое'];
const VITA = /^(A[1-4]|A3[.,]5|B[1-4]|C[1-4]|D[2-4]|BL[1-4]|OM[1-3]|[0-5]M[1-3](L|R)?([12][.,]5)?)$/i;
const DATE = /^(\d{2})\.(\d{2})\.(\d{4})$/;

const field = (k) => data[k] ?? {};
const conf = (k) => {
  const c = Number(field(k).confidence);
  return Number.isFinite(c) ? Math.max(0, Math.min(1, c)) : 0;
};
const str = (v) => (v == null ? '' : String(v).trim());
const issues = {};
const flag = (k, reason) => { if (!issues[k]) issues[k] = reason; };

// Значения
const number = str(field('order_number').value).replace(/\D/g, '');
const teeth = (Array.isArray(field('teeth').value) ? field('teeth').value : str(field('teeth').value).split(/\D+/))
  .map(Number).filter(Boolean);
const units = Number(str(field('units').value).replace(',', '.'));
const shade = str(field('shade').value).toUpperCase().replace(/\s/g, '');
const work = str(field('work_type').value);
const date = str(field('date').value);
const due = str(field('due_date').value);

// 152-ФЗ: в таблицу попадают только инициалы, даже если на бланке фамилия
const patientWords = str(field('patient_initials').value).split(/[\s.]+/).filter(Boolean);
const patient = patientWords.map(w => w[0].toUpperCase() + '.').join('');
if (patientWords.some(w => w.length > 1)) flag('patient_initials', 'на бланке ФИО — сохранены только инициалы');

// Проверки по смыслу
if (!/^\d{3,6}$/.test(number)) flag('order_number', 'нет номера');
const badTeeth = teeth.filter(t => !(t >= 11 && t <= 48 && t % 10 >= 1 && t % 10 <= 8));
if (!teeth.length) flag('teeth', 'пусто');
else if (badTeeth.length) flag('teeth', 'не FDI: ' + badTeeth.join(', '));
if (!Number.isInteger(units) || units <= 0) flag('units', 'не прочитано');
else if (teeth.length && units !== teeth.length) flag('units', `${units} ед. ≠ ${teeth.length} зуб.`);
if (!WORK.includes(work)) flag('work_type', work ? 'вне справочника' : 'пусто');
if (!VITA.test(shade)) flag('shade', shade ? 'не код VITA' : 'пусто');
const toDate = (s) => { const m = s.match(DATE); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; };
if (!toDate(date)) flag('date', date ? 'формат даты' : 'пусто');
if (!toDate(due)) flag('due_date', due ? 'формат даты' : 'пусто');
else if (toDate(date) && toDate(due) < toDate(date)) flag('due_date', 'срок раньше даты приёма');
for (const k of ['clinic', 'doctor']) if (!str(field(k).value)) flag(k, 'пусто');

// Справочник клиник и врачей: модель уверенно ошибается в 1–2 буквах рукописи
// («Ульябка» → «Улыбка»). Подтягиваем к ближайшему известному, неизвестное — на проверку.
const lev = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
};
const key = (s) => s.toLowerCase().replace(/ё/g, 'е').replace(/[^а-яa-z0-9]/g, '');
const snap = (k, list) => {
  const v = str(field(k).value);
  if (!v || !list.length) return v;
  const best = list.map(x => ({ x, d: lev(key(v), key(x)) })).sort((a, b) => a.d - b.d)[0];
  if (best.d === 0) return best.x;
  if (best.d <= Math.max(2, Math.floor(key(best.x).length / 4))) return best.x;
  flag(k, 'нет в справочнике');
  return v;
};
const clinic = snap('clinic', p.clinics || []);
const doctor = snap('doctor', p.doctors || []);

// Пороги уверенности: номер и количество — 0.9 (KPI 98 %), остальное — 0.7
for (const k of Object.keys(LABELS)) {
  const threshold = (k === 'order_number' || k === 'units') ? 0.9 : 0.7;
  if (k !== 'comment' && conf(k) < threshold) flag(k, `уверенность ${conf(k).toFixed(2)}`);
}
// Предупреждение по ФИО не блокирует наряд само по себе
const blocking = Object.keys(issues).filter(k => !(k === 'patient_initials' && issues[k].startsWith('на бланке')));
const status = blocking.length ? 'ПРОВЕРИТЬ' : 'OK';
const minConf = Math.min(...Object.keys(LABELS).filter(k => k !== 'comment').map(conf));
const now = $now.setZone('Europe/Moscow').toFormat('dd.MM.yyyy HH:mm');

const values = {
  order_number: number, date, clinic, doctor,
  patient_initials: patient, teeth: teeth.join(', '), work_type: work,
  units: Number.isInteger(units) ? units : '', shade, due_date: due, comment: str(field('comment').value),
};

const row = {
  'Получен': now, 'Номер': number, 'Дата': date, 'Клиника': values.clinic, 'Врач': values.doctor,
  'Пациент (инициалы)': patient, 'Зубы (FDI)': values.teeth, 'Вид работы': work, 'Кол-во': values.units,
  'Цвет VITA': shade, 'Срок': due, 'Комментарий': values.comment, 'Статус': status,
  'Спорные поля': Object.entries(issues).map(([k, r]) => `${LABELS[k]}: ${r}`).join('; '),
  'Мин. уверенность': Number(minConf.toFixed(2)), 'Фото работы': '', 'Модель': p.model,
};

// Журнал: одна строка на поле — оператор вносит своё значение, таблица считает точность
const journal = Object.keys(LABELS).map(k => ({
  'Получен': now, 'Номер': number, 'Поле': LABELS[k], 'Значение ИИ': String(values[k] ?? ''),
  'Уверенность': Number(conf(k).toFixed(2)), 'Ручное значение': '',
}));

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const line = (k) => {
  const v = values[k] === '' || values[k] == null ? '—' : values[k];
  return issues[k] ? `⚠️ <b>${LABELS[k]}: ${esc(v)}</b> — ${esc(issues[k])}` : `${LABELS[k]}: ${esc(v)}`;
};
const reply = [
  status === 'OK' ? `✅ <b>Наряд №${esc(number)} внесён</b>` : `🟡 <b>Наряд №${esc(number || '?')} — ПРОВЕРИТЬ</b>`,
  '',
  ...Object.keys(LABELS).map(line),
  '',
  status === 'OK' ? 'Статус: OK' : 'Статус: ПРОВЕРИТЬ — сверьте отмеченные поля с бланком в таблице.',
].join('\n');

return [{ json: { row, journal, reply, status, number } }];
